#include "test_support.hh"
#include <iomanip>
using namespace coarse_die;using namespace coarse_die_test;
int main(){json report;std::array<double,resource_count>rates{};rates[COMPUTE_GATE]=1;auto hw=manual_hardware(rates);
 Epoch e;e.name="no_initial_boundary_hint";e.credit_initial={{.5,0}};e.credit_capacity={{1,1}};auto a=activity(1,Role::Compute,COMPUTE_GATE,1);a.credit_delta={{-.25,0}};a.credit_curve={{0,{{0,0}}},{1,a.credit_delta}};e.activities={a};Runtime r(hw);r.submit(manual_plan(hw,{e},"nohint"),owner(1,1,1),0);r.advance_to(100000000);auto s=r.export_snapshot();auto bad=s;double rate=bad["executions"][0]["activities"][0]["rate"].get<double>();for(unsigned i=0;i<4;++i)rate=std::nextafter(rate,0.0);bad["executions"][0]["activities"][0]["rate"]=rate;bool rejected=false;try{(void)Runtime::import_snapshot(hw,bad);}catch(const std::invalid_argument&error){report["no_hint_feasible_4ulp_low_rejection"]=error.what();rejected=std::string(error.what()).find("published activity allocation differs")!=std::string::npos;}require(rejected,"missing hint does not accept a merely feasible rate");require(r.export_snapshot()==s,"failed import keeps parent unchanged");report["no_hint_parent_unchanged"]=true;
 // The single fixed witness has a hard owner envelope, independent of mirrors.
 Runtime owners(hw);for(unsigned i=0;i<33;++i)owners.submit(manual_plan(hw,{e},"owners"),owner(i+1,i+1,i+1),0);owners.advance_to(1000000);auto os=owners.export_snapshot();auto ob=os;ob["executions"][0]["activities"][0]["rate"]=0.0;rejected=false;try{(void)Runtime::import_snapshot(hw,ob);}catch(const std::invalid_argument&error){report["owner_limit_rejection"]=error.what();rejected=std::string(error.what()).find("32 fair owners")!=std::string::npos;}require(rejected,"fallback cannot exceed 32 unique fair owners");require(owners.export_snapshot()==os,"owner-limit failed import keeps parent unchanged");
 // 33 split executions with 17 fair owners and two inward initial-zero buffers
 // require 66 tautological rows. The fixed fallback refuses beyond 64.
 Epoch fill;fill.name="row_limit";fill.credit_initial={{0,0}};fill.credit_capacity={{1,1}};auto f=activity(1,Role::Compute,COMPUTE_GATE,1);f.credit_delta={{1,1}};f.credit_curve={{0,{{0,0}}},{1,f.credit_delta}};fill.activities={f};auto fp=manual_plan(hw,{fill},"row_limit");Runtime many(hw);for(unsigned i=0;i<33;++i)many.submit(fp,owner(i+1,i/2+1,i/2+1),0);many.advance_to(100000000);auto ms=many.export_snapshot();auto mb=ms;mb["executions"][0]["activities"][0]["rate"]=0.0;rejected=false;try{(void)Runtime::import_snapshot(hw,mb);}catch(const std::invalid_argument&error){report["row_limit_rejection"]=error.what();rejected=std::string(error.what()).find("64 extra rows")!=std::string::npos;}require(rejected,"fallback cannot exceed 64 redundant rows");require(many.export_snapshot()==ms,"row-limit failed import keeps parent unchanged");report["passed"]=true;std::cout<<report.dump(2)<<"\n";}
